          "হঠাৎ চিলেকোঠার দিক থেকে একটি মৃদু কিন্তু স্পষ্ট খসখস শব্দ শোনা গেল। মীর নিঃশব্দে হাত বাড়িয়ে একটি ভারী পিতলের বাতিদান তুলে নিল। সে ইশারায় বাকি দুজনকে পেছনের দিকে সরে যেতে বলল। ধীর পায়ে সে সিঁড়ির দিকে এগোতে লাগল। প্রতিটি কাঠের ধাপ অতিক্রম করার সময় বুকের ভেতরের হৃৎস্পন্দন কানে এসে বাজছিল।",
